// Mapa explícito, igual ao que já existe no L2 — sem fallback. Um
// tipo fora dessa lista é erro, não uma suposição de que é 'cliente'.
const mapaTipoDoctype = { cliente: 'Customer', produto: 'Item', fornecedor: 'Supplier' };
const doctype = mapaTipoDoctype[$json.tipo];

if (!doctype) {
  throw new Error('tipo_entidade inválido: "' + $json.tipo + '" — esperado cliente, produto ou fornecedor');
}

return [{ json: { ...$json, doctype } }];

const meta = $node['Mapeia tipo → Doctype'].json;
const registro = $input.first().json.data || {};

const system_prompt = 'Você é a Lyra, assistente do lojista dentro do painel Synapse. '
  + 'Responda a pergunta usando SOMENTE os dados fornecidos abaixo. Se a resposta '
  + 'não estiver nos dados, diga que não tem essa informação. Seja direto, uma ou '
  + 'duas frases, sem repetir a pergunta.\n\nDados do registro:\n' + JSON.stringify(registro);

// Migrado para a Lyra Central (/v1/chat) — não chama mais o Gemini direto nem
// depende de GEMINI_API_KEY. conversation_id exigido pelo contrato; chamada
// avulsa, usa o id de execução do n8n só pra rastreabilidade.
const conversation_id = 'lyra-consultar-' + $execution.id;

return [{ json: { conversation_id, system_prompt, user_prompt: meta.pergunta } }];

function parseSSE(texto) {
  const blocos = texto.split(/\r?\n\r?\n/).filter(Boolean);
  let tokens = '';
  let functionCall = null;
  let finishReason = null;
  for (const bloco of blocos) {
    const linhas = bloco.split(/\r?\n/);
    let evento = null;
    let dadosTexto = '';
    for (const linha of linhas) {
      if (linha.startsWith('event:')) evento = linha.slice(6).trim();
      if (linha.startsWith('data:')) dadosTexto += linha.slice(5).trim();
    }
    if (!evento || !dadosTexto) continue;
    let dados;
    try { dados = JSON.parse(dadosTexto); } catch (e) { continue; }
    if (evento === 'token') tokens += (dados.text || '');
    if (evento === 'function_call') functionCall = dados;
    if (evento === 'done') finishReason = dados.finish_reason;
  }
  return { tokens, functionCall, finishReason };
}

const bruto = $input.first().json.data ?? $input.first().json.body ?? $input.first().json;
const texto = typeof bruto === 'string' ? bruto : JSON.stringify(bruto);
const { tokens } = parseSSE(texto);

return [{ json: { texto_resposta: tokens } }];
